import { array, object, type JsonSchema } from "./render-defs.js";

const header = `// Generated by tooling/generate-types from definitions/composition.schema.json.
// Do not edit by hand.
`;

const categories = ["compositing", "output", "processing", "scene", "source", "vector"];
const portKinds = ["raster", "scene"];
const constraintKeys = ["min", "max", "step", "format", "multiline", "recommendedRows", "role"];

type Json = Record<string, unknown>;

const identifier = /^[A-Za-z_$][A-Za-z0-9_$]*$/u;

/** `value` as a one-line TypeScript literal. */
function literal(value: unknown): string {
  if (Array.isArray(value)) return `[${value.map(literal).join(", ")}]`;
  if (value !== null && typeof value === "object") {
    const fields = Object.entries(value).map(
      ([key, field]) => `${identifier.test(key) ? key : JSON.stringify(key)}: ${literal(field)}`,
    );
    return fields.length === 0 ? "{}" : `{ ${fields.join(", ")} }`;
  }
  return JSON.stringify(value);
}

function text(owner: string, source: Json, key: string): string {
  const value = source[key];
  if (typeof value !== "string") throw new Error(`${owner} has no \`${key}\``);
  return value;
}

function oneOf(owner: string, value: unknown, allowed: readonly string[]): string {
  if (typeof value !== "string" || !allowed.includes(value)) {
    throw new Error(`${owner} has ${JSON.stringify(value)}, not one of ${allowed.join(", ")}`);
  }
  return value;
}

function number(value: unknown): number | undefined {
  return typeof value === "number" && Number.isFinite(value) ? value : undefined;
}

function constraints(param: Json): Json | undefined {
  const source = object(param["x-lumen-constraints"]);
  const found: Json = {
    min: number(source.min ?? param.minimum),
    max: number(source.max ?? param.maximum),
    step: number(source.step),
    format: typeof source.format === "string" ? source.format : undefined,
    multiline: typeof source.multiline === "boolean" ? source.multiline : undefined,
    recommendedRows: number(source.recommendedRows),
    role: typeof source.role === "string" ? source.role : undefined,
  };
  const present = constraintKeys.filter((key) => found[key] !== undefined);
  return present.length === 0
    ? undefined
    : Object.fromEntries(present.map((key) => [key, found[key]]));
}

function enumOptions(owner: string, value: unknown): Json[] | undefined {
  if (value === undefined) return undefined;
  return array(value).map((item) => {
    const option = object(item);
    const optionValue = number(option.value);
    if (optionValue === undefined) throw new Error(`${owner} has an enum option without a value`);
    return {
      name: text(owner, option, "name"),
      label: text(owner, option, "label"),
      value: optionValue,
    };
  });
}

function paramSpec(kind: string, id: string, schema: unknown): Json {
  const owner = `\`${kind}\` param \`${id}\``;
  const param = object(schema);
  const spec: Json = {
    id,
    name: text(owner, param, "title"),
    kind: text(owner, param, "x-lumen-kind"),
    description: text(owner, param, "description"),
  };
  if ("default" in param) spec.defaultValue = param.default;
  const options = enumOptions(owner, param["x-lumen-enumOptions"]);
  if (options !== undefined) spec.enumOptions = options;
  const limits = constraints(param);
  if (limits !== undefined) spec.constraints = limits;
  return spec;
}

function nodeSpec(nodeSchema: unknown): Json {
  const node = object(nodeSchema);
  const properties = object(node.properties);
  const kind = object(properties.type).const;
  if (typeof kind !== "string") throw new Error("a node schema has no `type` constant");
  const owner = `\`${kind}\``;
  const params = Object.entries(object(object(properties.params).properties)).map(([id, param]) =>
    paramSpec(kind, id, param),
  );
  return {
    kind,
    name: text(owner, node, "title"),
    description: text(owner, node, "description"),
    category: oneOf(`${owner} category`, node["x-lumen-category"], categories),
    inputs: array(node["x-lumen-inputs"]).map((item) => {
      const port = object(item);
      return {
        name: text(owner, port, "name"),
        kind: oneOf(`${owner} input kind`, port.kind, portKinds),
        optional: Boolean(port.optional),
        variadic: Boolean(port.variadic),
      };
    }),
    outputs: array(node["x-lumen-outputs"]).map((item) => {
      const port = object(item);
      return {
        name: text(owner, port, "name"),
        kind: oneOf(`${owner} output kind`, port.kind, portKinds),
      };
    }),
    params,
    defaultParams: Object.fromEntries(
      params.flatMap((param) =>
        param.defaultValue === undefined ? [] : [[param.id, param.defaultValue]],
      ),
    ),
  };
}

function renderSpec(spec: Json): string {
  const lines = (items: readonly unknown[]): string =>
    items.length === 0
      ? "[]"
      : `[\n${items.map((item) => `      ${literal(item)},`).join("\n")}\n    ]`;
  return `  {
    kind: ${literal(spec.kind)},
    name: ${literal(spec.name)},
    description: ${literal(spec.description)},
    category: ${literal(spec.category)},
    inputs: ${lines(spec.inputs as unknown[])},
    outputs: ${lines(spec.outputs as unknown[])},
    params: ${lines(spec.params as unknown[])},
    defaultParams: ${literal(spec.defaultParams)},
  },`;
}

/** The contents of `generated/node-specs.ts`: what the schema says about every node kind. */
export function renderNodeSpecs(schema: JsonSchema): string {
  const nodeSchemas = array(object(object(object(schema.properties).nodes).items).oneOf);
  if (nodeSchemas.length === 0) throw new Error("the composition schema has no node definitions");
  return `${header}
import type { NodeKind } from "./meta.js";
import type { NodeSpec } from "../node-spec.js";

/** What the schema says about every node kind, in the schema's order. */
export const nodeSpecs: readonly NodeSpec[] = [
${nodeSchemas.map((nodeSchema) => renderSpec(nodeSpec(nodeSchema))).join("\n")}
];

/** The spec of each node kind. */
export const nodeSpecByKind = Object.fromEntries(
  nodeSpecs.map((spec) => [spec.kind, spec]),
) as Readonly<Record<NodeKind, NodeSpec>>;
`;
}
